def transform(grid):
    """Insert an 8-colored line at the far edge of the object, sliding it toward the solid 2 separator."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))

    # Locate full, non-background separator lines.
    separators = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            separators.append(("h", r, row[0]))
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != bg:
            separators.append(("v", c, col[0]))

    # The object consists of non-background, non-separator cells.
    object_cells = [(r, c) for r in range(h) for c in range(w)
                    if grid[r][c] != bg and not any(grid[r][c] == color and
                    ((orient == "h" and r == pos) or (orient == "v" and c == pos))
                    for orient, pos, color in separators)]
    if not object_cells:
        return out

    # Use the line that separates the large object-bearing region from the rest.
    for orient, pos, color in separators:
        if orient == "h":
            before = [(r, c) for r, c in object_cells if r < pos]
            after = [(r, c) for r, c in object_cells if r > pos]
            side = before if before and not after else after if after and not before else []
            if not side:
                continue
            if side is before:
                edge = min(r for r, c in side)
                # Shift the entire strip one row toward the separator, keeping it fixed.
                for r in range(pos - 1, edge, -1):
                    out[r] = grid[r - 1][:]
                out[edge] = [8] * w
            else:
                edge = max(r for r, c in side)
                for r in range(pos + 1, edge):
                    out[r] = grid[r + 1][:]
                out[edge] = [8] * w
        else:
            left = [(r, c) for r, c in object_cells if c < pos]
            right = [(r, c) for r, c in object_cells if c > pos]
            side = left if left and not right else right if right and not left else []
            if not side:
                continue
            if side is left:
                edge = min(c for r, c in side)
                for c in range(pos - 1, edge, -1):
                    for r in range(h):
                        out[r][c] = grid[r][c - 1]
                for r in range(h):
                    out[r][edge] = 8
            else:
                edge = max(c for r, c in side)
                for c in range(pos + 1, edge):
                    for r in range(h):
                        out[r][c] = grid[r][c + 1]
                for r in range(h):
                    out[r][edge] = 8
        return out
    return out

