def transform(grid):
    """Shift the non-background figure one cell toward a solid separator, marking the vacated edge in 8."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))

    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            # Horizontal separator. Shift the contents on its occupied side toward it.
            color = row[0]
            above = any(grid[i][j] not in (bg, color) for i in range(r) for j in range(w))
            below = any(grid[i][j] not in (bg, color) for i in range(r + 1, h) for j in range(w))
            if above and not below:
                first = min(i for i in range(r) for j in range(w) if grid[i][j] not in (bg, color))
                for i in range(r - 1, first, -1):
                    out[i] = grid[i - 1][:]
                out[first] = [8] * w
                return out
            if below and not above:
                last = max(i for i in range(r + 1, h) for j in range(w) if grid[i][j] not in (bg, color))
                for i in range(r + 1, last):
                    out[i] = grid[i + 1][:]
                out[last] = [8] * w
                return out

    for c in range(w):
        col = [grid[i][c] for i in range(h)]
        if len(set(col)) == 1 and col[0] != bg:
            color = col[0]
            left = any(grid[i][j] not in (bg, color) for i in range(h) for j in range(c))
            right = any(grid[i][j] not in (bg, color) for i in range(h) for j in range(c + 1, w))
            if left and not right:
                first = min(j for i in range(h) for j in range(c) if grid[i][j] not in (bg, color))
                for j in range(c - 1, first, -1):
                    for i in range(h):
                        out[i][j] = grid[i][j - 1]
                for i in range(h):
                    out[i][first] = 8
                return out
            if right and not left:
                last = max(j for i in range(h) for j in range(c + 1, w) if grid[i][j] not in (bg, color))
                for j in range(c + 1, last):
                    for i in range(h):
                        out[i][j] = grid[i][j + 1]
                for i in range(h):
                    out[i][last] = 8
                return out
    return out

