                out[i] = grid[i - 1][:]
            out[edge] = [8] * w
        elif below and not above:
            edge = max(i for i, j in below)
            for i in range(r + 1, edge):
                out[i] = grid[i + 1][:]
            out[edge] = [8] * w
        return out
    return out

