                    out[r + shift][c] = grid[r][c]
                out[target_edge - 1] = [8] * w
            else:
                shift = sr + 1 - min(r for r, c in below)
                target_edge = max(r for r, c in below) + shift
                for r, c in cells:
                    out[r][c] = bg
                for r, c in below:
                    out[r + shift][c] = grid[r][c]
                out[target_edge + 1] = [8] * w
