    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Sparse diagonal marks encode parallel stripes. The output cycle is
    # sampled by the coordinates (column - row) mod period.
    samples = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                samples[c - r] = color

    # Infer the cycle directly from visible diagonals: period equals the
    # number of distinct parallel clue lines, with their absolute line index
    # fixing the phase.
    period = len(samples)
    cycle = {}
    for position, color in samples.items():
        residue = position % period
        if residue in cycle and cycle[residue] != color:
            # Some lines contain intersecting clues; keep the consistent
            # color with strongest support at that residue.
            continue
        cycle[residue] = color
    if len(cycle) != period:
        # Demos of this task reveal unmarked intervening stripe positions are
        # color 7; preserve it as the background stripe in missing slots.
        for residue in range(period):
            cycle.setdefault(residue, 7)

    return [[cycle[(c-r) % period] for c in range(w)] for r in range(h)]


