def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Sparse diagonal clues describe two overlapping lines of repeated color
    # stripes. Complete the two families independently: c-r for down-right,
    # and c+r for down-left. Values 0 are not clues.
    result = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            result[r][c] = 0

    # Separate the visible colored tracks by their diagonal invariants. The
    # task's diagonal examples establish that cells in these tracks repeat
    # their color periodically with a motif period equal to the clue-grid span.
    dr, dl = {}, {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                dr.setdefault(c-r, []).append(color)
                dl.setdefault(c+r, []).append(color)

    # A consistent line family has uniform colors; choose the family with
    # longest aligned runs, and build the minimal complete periodic template.
    def strength(groups):
        return max((len(v) for v in groups.values()), default=0)
    use_left = strength(dl) > strength(dr)
    groups = dl if use_left else dr
    line_colors = {}
    for k, vals in groups.items():
        counts = {v: vals.count(v) for v in set(vals)}
        line_colors[k] = max(counts, key=counts.get)

    lo, hi = min(line_colors), max(line_colors)
    span = hi - lo + 1
    motif = [None] * span
    for k, color in line_colors.items():
        motif[k-lo] = color

    # Empty gaps between clue lines are background-color bands; the demos with
    # adjacent colored stripe tracks show that those gaps are filled by the
    # background color, not by copying the nearest clue stripe.
    background = 0
    for i in range(span):
        if motif[i] is None:
            motif[i] = background

    if use_left:
        return [[motif[(r+c-lo) % span] for c in range(w)] for r in range(h)]
    return [[motif[(c-r-lo) % span] for c in range(w)] for r in range(h)]


