def transform(grid):
    """Infer periodic row stripes, or fill the marked diagonal rays."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Full-width horizontal clues specify a repeating row-color cycle.
    row_samples = {r: row[0] for r, row in enumerate(grid)
                   if row[0] != 0 and all(value == row[0] for value in row)}
    if row_samples:
        # Cycle is the observed sequence of stripe colors in row order, repeated.
        cycle = [row_samples[r] for r in sorted(row_samples)]
        return [[cycle[r % len(cycle)] for _ in range(w)] for r in range(h)]

    # The diagonal examples show a ray-like pattern: extend each marked
    # diagonal line with the color of its observed clue, leaving all other
    # cells as background. Lines are tracked by c-r and c+r.
    result = [[0 for _ in range(w)] for _ in range(h)]
    dr, dl = {}, {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                dr.setdefault(c-r, []).append((r,c,color))
                dl.setdefault(c+r, []).append((r,c,color))
    use_left = max((len(v) for v in dl.values()), default=0) > max(
        (len(v) for v in dr.values()), default=0)
    lines = dl if use_left else dr
    for index, marks in lines.items():
        counts = {}
        for _, _, color in marks:
            counts[color] = counts.get(color, 0) + 1
        color = max(counts, key=counts.get)
        for r in range(h):
            c = index - r if use_left else index + r
            if 0 <= c < w:
                result[r][c] = color
    return result


