def transform(grid):
    """Fill a grid with the color-cycle pattern indicated by its sparse stripes."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Horizontal full-width monochrome clues encode a cycle of row bands.
    row_samples = {r: row[0] for r, row in enumerate(grid)
                   if row[0] != 0 and all(v == row[0] for v in row)}
    if row_samples:
        # Demos show repeating row colors in the order they occur by row index.
        cycle = [row_samples[r] for r in sorted(row_samples)]
        return [[cycle[r % len(cycle)] for _ in range(w)] for r in range(h)]

    # Diagonal cases: repeated rows in the output correspond to a period along
    # the column coordinate, with clue runs establishing its phase and colors.
    # Find a shortest consistent column period; unlike diagonal extrapolation,
    # this respects runs appearing on the same input row.
    samples = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                samples.setdefault(c, []).append(color)
    for period in range(1, w + 1):
        cycle = {}
        valid = True
        for c, colors in samples.items():
            residue = c % period
            for color in colors:
                if residue in cycle and cycle[residue] != color:
                    valid = False
                    break
                cycle[residue] = color
            if not valid:
                break
        if valid:
            # Fill undetermined residues from closest constrained column.
            for residue in range(period):
                if residue not in cycle:
                    nearest = min(cycle, key=lambda k: min((residue-k) % period,
                                                           (k-residue) % period))
                    cycle[residue] = cycle[nearest]
            return [[cycle[c % period] for c in range(w)] for _ in range(h)]
    return [row[:] for row in grid]


